  async function getAccumExamplesForUnit(unitId) {
    const all = await db().getAll(STORES.USER_PROGRESS);
    const map = {};
    for (const r of all) {
      if (r.id.startsWith(`accum:${unitId}:`) && r.example) map[r.idx] = r.example;
    }
    return map;
  }
  var rvId = (unitId) => `review:${unitId}`;
