                q("q3", "\u4F60\u5BB6\u4E61\u6709\u6CA1\u6709\u8FD9\u6837\u65B9\u4FBF\u5927\u5BB6\u7684\u5C0F\u8BBE\u65BD\uFF08\u5982\u5C0F\u6865\u3001\u77F3\u9636\uFF09\uFF1F\u5B83\u4F53\u73B0\u4E86\u4EC0\u4E48\uFF1F", `\u793A\u4F8B\uFF1A\u6751\u53E3\u5C0F\u6728\u6865\u3002\u5B83\u65B9\u4FBF\u5927\u5BB6\u8FC7\u6CB3\uFF0C\u4F53\u73B0\u4E61\u4EB2\u4EEC\u4E92\u5E2E\u4E92\u52A9\u3001\u5C31\u5730\u53D6\u6750\u7684\u6734\u5B9E\u667A\u6167\u3002\u80FD\u4E3E\u51FA\u4FBF\u5229\u8BBE\u65BD\u5E76\u8BF4\u660E\u5373\u53EF\u3002`, "\u60C5\u611F\u8981\u7D20", "basic")
