              L2: [
                q("q2", '"\u642D\u77F3\uFF0C\u6784\u6210\u4E86\u5BB6\u4E61\u7684\u4E00\u9053\u98CE\u666F"\u4E2D"\u98CE\u666F"\u6307\u4EC0\u4E48\uFF1F\u4EC5\u4EC5\u6307\u81EA\u7136\u666F\u8272\u5417\uFF1F', `\u4E0D\u4EC5\u6307\u5C0F\u6EAA\u642D\u77F3\u7684\u81EA\u7136\u666F\u81F4\uFF0C\u66F4\u6307\u4E61\u4EB2\u4EEC\u9ED8\u9ED8\u6446\u77F3\u3001\u4E3B\u52A8\u4FEE\u6574\u3001\u4E92\u76F8\u5173\u5FC3\u7684\u7F8E\u597D\u5FC3\u7075\u4E0E\u4E61\u98CE\uFF0C\u662F\u4E00\u9053\u4EBA\u60C5"\u98CE\u666F"\u3002`, "\u8BCD\u53E5\u7406\u89E3", "basic")
              ],
              L3: [
                q("q3", "\u4ECE\u8001\u4EBA\u4FEE\u642D\u77F3\u8FD9\u4EF6\u4E8B\uFF0C\u4F60\u770B\u51FA\u4E86\u4E61\u4EB2\u4EEC\u600E\u6837\u7684\u54C1\u8D28\uFF1F", `\u770B\u51FA\u4E61\u4EB2\u4EEC\u52E4\u52B3\u3001\u8D1F\u8D23\u4EFB\u3001\u5FC3\u91CC\u88C5\u7740\u522B\u4EBA\u3001\u9ED8\u9ED8\u5949\u732E\u7684\u54C1\u8D28\uFF0C\u54EA\u6015\u6025\u7740\u8D76\u8DEF\u4E5F\u8981\u628A\u642D\u77F3\u4FEE\u7A33\uFF0C\u4E3A\u4ED6\u4EBA\u7740\u60F3\u3002`, "\u60C5\u611F\u8981\u7D20", "basic")
              ]
