  async function onRecord(a, btn) {
    if (!navigator.mediaDevices || !window.MediaRecorder) {
      alert("\u5F53\u524D\u73AF\u5883\u4E0D\u652F\u6301\u5F55\u97F3\uFF08\u9700\u6D4F\u89C8\u5668\u6388\u4E88\u9EA6\u514B\u98CE\u6743\u9650\uFF09");
      return;
    }
    const rid = a.rid;
    if (!recorders[rid]) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const rec = new MediaRecorder(stream);
        const chunks = [];
        rec.ondataavailable = (ev) => {
          if (ev.data.size) chunks.push(ev.data);
        };
        rec.onstop = async () => {
          const blob = new Blob(chunks, { type: rec.mimeType || "audio/webm" });
          const dur = Math.round((Date.now() - recorders[rid].start) / 1e3);
          await saveAudio({ lessonId: a.lesson, segmentId: a.seg, level: Number(a.lv), questionId: a.qid, blob, mime: blob.type, durationSec: dur });
          stream.getTracks().forEach((tk) => tk.stop());
          delete recorders[rid];
          render();
        };
        rec.start();
        recorders[rid] = { recorder: rec, chunks, start: Date.now() };
        btn.textContent = "\u23F9 \u505C\u6B62";
      } catch (err) {
        alert("\u65E0\u6CD5\u8BBF\u95EE\u9EA6\u514B\u98CE\uFF1A" + err.message);
      }
    } else {
      recorders[rid].recorder.stop();
    }
  }
